import{_ as r,C as a,o as s,c as i,aj as e,E as d}from"./framework.js";const u=JSON.parse('{"title":"Files | Content | Admin CMS","description":"Files manages the site CMS file library: upload PDFs, ZIPs, documents, etc., organize by folder, and serve downloads or access via site URLs. This is not the same storage as top-bar…","frontmatter":{"title":"Files | Content | Admin CMS","description":"Files manages the site CMS file library: upload PDFs, ZIPs, documents, etc., organize by folder, and serve downloads or access via site URLs. This is not the same storage as top-bar…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/content/files.html"}]]},"headers":[],"relativePath":"cms/content/files.md","filePath":"en/cms/content/files.md","lastUpdated":1781010536000}'),n={name:"cms/content/files.md"};function l(c,t,h,g,p,m){const o=a("DocImage");return s(),i("div",null,[t[0]||(t[0]=e('<h1 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h1><blockquote><p>Menu: <strong>Content → Files</strong> (must be enabled in <strong>Edit Menu</strong>; route <code>advanced: true</code>)<br> Deep link: <code>/_Admin/content/files?SiteId={siteGuid}</code><br> Common query parameters: <code>folder</code> (current path, default <code>/</code>), <code>keyword</code> (search term), <code>provider</code> (storage provider, default <code>default</code>)</p></blockquote><p><strong>Files</strong> manages the site <strong>CMS file library</strong>: upload PDFs, ZIPs, documents, etc., organize by folder, and serve downloads or access via site <strong>URLs</strong>. This is not the same storage as top-bar <strong><a href="./../site/media.html">Media library</a></strong> (images/media, <code>k.media</code>).</p><div class="warning custom-block"><p class="custom-block-title">Not the same as k.file</p><table tabindex="0"><thead><tr><th></th><th><strong>Content → Files</strong> (this page)</th><th><strong><a href="/kb-docs/api/file/file.html">k.file</a></strong></th></tr></thead><tbody><tr><td>Purpose</td><td>Admin UI management; routable CMS files</td><td>KScript read/write on site disk files</td></tr><tr><td>Admin UI</td><td><strong>Yes</strong> (this page)</td><td><strong>No</strong> dedicated visual UI</td></tr><tr><td>Script API</td><td>Currently <strong>no</strong> dedicated <code>k.xxx</code> for this library</td><td><code>k.file.read</code> / <code>write</code>, etc.</td></tr></tbody></table><p>Do not treat this page as the admin entry for <code>k.file</code>; <strong>File</strong> field values on content entries also point to resources in <strong>this CMS file library</strong>, not <code>k.file</code> paths.</p></div><div class="tip custom-block"><p class="custom-block-title">Where to put images?</p><p>UI guidance: <strong>images and icons</strong> for the site should go in the <strong>media library</strong>; this page suits attachments, downloadable documents, and other <strong>non-image-primary</strong> site files.</p></div><div class="tip custom-block"><p class="custom-block-title">How to see this menu</p><p>If <strong>Files</strong> is missing under <strong>Content</strong>, open <strong>Edit Menu</strong> (<code>editMenu</code>, show/hide infrequent items), check <strong>Files</strong>, and save. See <a href="./../navigation.html#edit-menu">Menu overview · Edit Menu</a>.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>Enter the site admin (<code>SiteId</code> in the address bar).</li><li>After enabling <strong>Files</strong> in <strong>Edit Menu</strong>, open <strong>Content → Files</strong>.</li><li>When entering subfolders or searching, the address bar updates <code>folder</code>, <code>keyword</code>, and <code>provider</code>.</li></ol>',8)),d(o,{src:"/cms/content/files-list.png",alt:"Content · Files list",width:"1120"}),t[1]||(t[1]=e('<h2 id="ui-overview" tabindex="-1">UI Overview <a class="header-anchor" href="#ui-overview" aria-label="Permalink to &quot;UI Overview&quot;">​</a></h2><h3 id="breadcrumb" tabindex="-1">Breadcrumb <a class="header-anchor" href="#breadcrumb" aria-label="Permalink to &quot;Breadcrumb&quot;">​</a></h3><p>Path from <strong>Files</strong> (root) to the current folder; click to go up.</p><h3 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td>Select all</td><td>Select files and folders on the current page</td></tr><tr><td>Upload</td><td>Upload one or more files to the <strong>current folder</strong>; <strong>unavailable while searching</strong></td></tr><tr><td>New folder</td><td>Create a subfolder at the current path; unavailable while searching</td></tr><tr><td>Download</td><td>Download selected files/folders as a package</td></tr><tr><td>Delete</td><td>Batch delete selection (permission <code>file</code> · <code>delete</code>)</td></tr><tr><td>Search / provider</td><td>Keyword search on the right; if multiple <strong>providers</strong> are configured, switch tabs (<code>provider</code>)</td></tr></tbody></table><p>Single file size limit is about <strong>150 MB</strong> (prompt if exceeded). If a file with the same name exists at the target path, upload prompts whether to overwrite.</p><h3 id="list-columns" tabindex="-1">List columns <a class="header-anchor" href="#list-columns" aria-label="Permalink to &quot;List columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column / action</th><th>Description</th></tr></thead><tbody><tr><td>File name</td><td>File or folder name; click folder to enter</td></tr><tr><td>URL</td><td>Access path on the site (copy for page links or content fields)</td></tr><tr><td>References</td><td>Which site resources reference this file (if any)</td></tr><tr><td>Size</td><td>File size</td></tr><tr><td>Last modified</td><td>Update time</td></tr><tr><td>Row actions</td><td><strong>Open containing folder</strong>, <strong>Copy URL</strong>, <strong>Preview</strong> (when applicable), <strong>Download</strong></td></tr></tbody></table><p>Pagination at the bottom; some providers support <strong>infinite scroll</strong> for more (per API).</p><h2 id="typical-usage" tabindex="-1">Typical Usage <a class="header-anchor" href="#typical-usage" aria-label="Permalink to &quot;Typical Usage&quot;">​</a></h2><h3 id="upload-downloadable-attachments" tabindex="-1">Upload downloadable attachments <a class="header-anchor" href="#upload-downloadable-attachments" aria-label="Permalink to &quot;Upload downloadable attachments&quot;">​</a></h3><ol><li><strong>Content → Files</strong>, open the target folder (e.g. <code>/downloads</code>).</li><li><strong>Upload</strong> local PDF/ZIP, etc.</li><li>Copy <strong>URL</strong> from the list for HTML, rich text, or templates (site routing serves file content via CmsFile).</li></ol><h3 id="select-files-in-content-fields" tabindex="-1">Select files in content fields <a class="header-anchor" href="#select-files-in-content-fields" aria-label="Permalink to &quot;Select files in content fields&quot;">​</a></h3><p>When a <a href="./content-types.html">content type</a> field uses <strong>File</strong> (optionally <strong>Enable multiple</strong>), <strong>Select file</strong> in the entry form opens the same browser dialog as this page (<code>KFileDialog</code>); selection writes the CMS file <strong>URL/key</strong> to the entry.</p><h3 id="comparison-with-media-library" tabindex="-1">Comparison with media library <a class="header-anchor" href="#comparison-with-media-library" aria-label="Permalink to &quot;Comparison with media library&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th><strong>Files</strong> (this page, CmsFile)</th><th><strong>Media library</strong></th></tr></thead><tbody><tr><td>Menu</td><td>Content → Files</td><td>Top-bar media library</td></tr><tr><td>Typical content</td><td>PDF, ZIP, attachments</td><td>Images, display media</td></tr><tr><td>Content fields</td><td><strong>File</strong> control</td><td><strong>Image</strong> / <strong>Advanced image</strong></td></tr><tr><td>Script</td><td>No dedicated <code>k.xxx</code> yet</td><td><code>k.media</code></td></tr></tbody></table><h2 id="development-notes" tabindex="-1">Development Notes <a class="header-anchor" href="#development-notes" aria-label="Permalink to &quot;Development Notes&quot;">​</a></h2><ul><li>For <strong>script read/write on disk</strong> (logs, temp import files, etc.), use <a href="/kb-docs/api/file/file.html">k.file</a>; unrelated to <strong>Content → Files</strong> here.</li><li>Public access to CMS library files is usually via <strong>URL</strong> copied from the admin list or front-end routing, not <code>k.file</code> paths.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./../site/media.html">Media library</a></td><td>Images and media</td></tr><tr><td><a href="./content-types.html">Content types</a></td><td><strong>File</strong> field control</td></tr><tr><td><a href="/kb-docs/api/file/file.html">k.file</a></td><td>Disk file KScript API (not this page)</td></tr><tr><td><a href="./">Content overview</a></td><td>Content group menu</td></tr></tbody></table>',20))])}const b=r(n,[["render",l]]);export{u as __pageData,b as default};
